package jp.tapmarker;
import java.util.*;
public final class FarmPreset {
 public static final String APP="com.kurashiru.nouen.usagi",P="farm-default-";
 static void region(PhaseEngine e,String id,String name,float...b){PhaseEngine.Region r=new PhaseEngine.Region();r.id=P+id;r.name=name;r.bounds=b;e.regions.put(r.id,r);}
 static void state(PhaseEngine e,String id,String name){PhaseEngine.Phase p=new PhaseEngine.Phase();p.id=P+id;p.name="農園うさぎ："+name;p.markersDuring=id.equals("main");int n=e.phases.size();p.graphX=(n%3)*300;p.graphY=(n/3)*180;e.phases.put(p.id,p);}
 static void image(PhaseEngine e,Map<String,float[]> refs,String state,String id,String roi,int condition,int action,String next,boolean fallback){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=P+id;w.name=id;w.regionId=P+roi;w.condition=condition;w.action=action;w.nextPhase=P+next;w.reference=refs.get(roi).clone();w.waitMs=0;w.fallback=fallback;e.phases.get(P+state).watches.add(w);}
 static void timer(PhaseEngine e,String state,long ms,int action,String next){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=P+state+"-timeout";w.name="表示確認の上限";w.condition=PhaseEngine.TIMEOUT;w.action=action;w.nextPhase=next.isEmpty()?"":P+next;w.timeoutMs=ms;w.waitMs=0;w.fallback=true;e.phases.get(P+state).watches.add(w);}
 static boolean chestControls(PhaseEngine e){if(!e.phases.containsKey(P+"chest"))return false;boolean changed=false;if(!e.regions.containsKey(P+"chest-open")){region(e,"chest-open","宝箱を開ける（実際のボタン位置を取得）",0,0,1,1);changed=true;}for(String state:new String[]{"main","check","ad","verify","chest"})if(e.phases.containsKey(P+state)&&e.rule(P+state+"-chest-open")==null){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=P+state+"-chest-open";w.name="宝箱を開ける";w.regionId=P+"chest-open";w.condition=PhaseEngine.MATCH;w.reference=new float[]{1};w.action=state.equals("chest")?PhaseEngine.CENTER:PhaseEngine.WAIT;w.nextPhase=P+(state.equals("chest")?"check":"chest");w.waitMs=0;e.phases.get(P+state).watches.add(w);changed=true;}return changed;}
 static void classify(PhaseEngine e,Map<String,float[]> r,String state){image(e,r,state,state+"-reward","close",1,5,"reward",false);image(e,r,state,state+"-bonus","start",1,5,"bonus",false);image(e,r,state,state+"-chest","chest",1,5,"chest",false);image(e,r,state,state+"-home","harvest",1,5,"main",true);}
 public static boolean install(PhaseEngine e,Map<String,float[]> r){if(e.phases.containsKey(P+"main"))return false;for(String key:new String[]{"harvest","close","start","chest","upgrade"})if(r.get(key)==null)throw new IllegalArgumentException("農園画像がありません："+key);
 region(e,"harvest","主画面右上の固定ヘルプ",.75f,.077f,.805f,.092f);region(e,"close","コイン獲得の閉じる",.40f,.648f,.60f,.676f);region(e,"start","広告を使わずこのままはじめる",.34f,.831f,.68f,.85f);region(e,"chest","宝箱の鍵",.45f,.525f,.53f,.58f);region(e,"upgrade","スコップ強化の必要表示",.07f,.80f,.14f,.823f);
 String[] ids={"main","check","reward","bonus","chest","upgrade-wait","ad","verify","unknown"};String[] names={"収穫・フィーバー","画面判別","コイン獲得を閉じる","次の収穫を開始","宝箱演出","スコップ強化後の確認","CMから復帰","復帰確認","未確認画面で停止"};for(int i=0;i<ids.length;i++)state(e,ids[i],names[i]);
 image(e,r,"main","reward-shown","close",1,5,"reward",false);image(e,r,"main","bonus-shown","start",1,5,"bonus",false);image(e,r,"main","chest-shown","chest",1,5,"chest",false);image(e,r,"main","home-lost","harvest",3,5,"check",true);image(e,r,"main","upgrade-ready","upgrade",1,0,"upgrade-wait",true);
 classify(e,r,"check");timer(e,"check",5000,5,"ad");image(e,r,"reward","close-tap","close",1,0,"check",false);timer(e,"reward",4000,5,"check");image(e,r,"bonus","start-tap","start",1,0,"verify",false);timer(e,"bonus",4000,5,"check");timer(e,"chest",1500,5,"check");timer(e,"upgrade-wait",700,5,"check");classify(e,r,"ad");timer(e,"ad",1500,6,"verify");classify(e,r,"verify");timer(e,"verify",6000,6,"verify");timer(e,"unknown",0,4,"");chestControls(e);e.rule(P+"upgrade-ready").threshold=.02f;e.initial=P+"main";e.current=e.initial;return true;
 }
 public static boolean upgrade(PhaseEngine e){boolean changed=chestControls(e);PhaseEngine.Watch w=e.rule(P+"upgrade-ready");PhaseEngine.Region r=e.regions.get(P+"upgrade");if(w==null||r==null||w.condition!=PhaseEngine.MATCH||w.action!=PhaseEngine.CENTER||!w.regionId.equals(P+"upgrade")||w.threshold!=.004f||!Arrays.equals(r.bounds,new float[]{.07f,.80f,.14f,.823f}))return changed;w.threshold=.02f;return true;}
 public static boolean home(PhaseEngine e,Map<String,float[]> samples){float[] error=samples.get(FarmAdErrorEvidence.KEY);if(error!=null&&error.length==1&&error[0]==1)return false;PhaseEngine.Watch w=e.rule(P+"verify-home");float[] s=samples.get(P+"harvest");return w!=null&&s!=null&&w.distance(s)<=w.threshold;}
}
